              slide.css('opacity', 1);
              if (Math.abs(slideProgress) > 1.28) {
                slide.css('opacity', 0);
              }
            }
          },
          setTransition: function (transition) {
            for (let i = 0; i < this.slides.length; i++) {
              const slide = this.slides.eq(i);
              slide.transition(transition);
            }
          },
        },
      },
      swiperBottomCardOption: {
        slidesPerView: 5,
        slidesPerGroup: 1,
        centeredSlides: true,
        loop: true,
        loopedSlides: 5,
        slideToClickedSlide: true,
      },
      // match
      rightSwiperOption: {
        slidesPerView: 1,
        slidesPerGroup: 1,
        speed: 800,
        pagination: {
          el: '#home .match .swiper-pagination',
          type: 'fraction',
        },
        navigation: {
          prevEl: '#home .match .swiper-button-prev',
          nextEl: '#home .match .swiper-button-next',
        },
      },
      leftSwiperOption: {
        slidesPerView: 1,
        slidesPerGroup: 1,
        speed: 800,
        observer: true, // 开启 observer 功能
        observeParents: true,
      },
    };
  },
  computed: {
    pageCode() {
      return pageCode;
    },
    caseTopSwiper() {
      return this.$refs.caseTopSwiper.$swiper;
    },
    caseBottomSwiper() {
      return this.$refs.caseBottomSwiper.$swiper;
    },
    matchLeftSwiper() {
      return this.$refs.leftSwiperBox.$swiper;
    },
    matchRightSwiper() {
      return this.$refs.rightSwiperBox.$swiper;
    },
  },
  mounted() {
    this.$nextTick(() => {
      AOS.init({
        mirror: true,
      });
    });
    this.rightFirstSvgArrow = anime({
      targets: '.movingSvg path',
      strokeDashoffset: [anime.setDashoffset, 0],
      easing: 'easeInOutSine',
      duration: 800,
      delay: function (el, i) {
        return i * 250;
      },
      direction: 'normal',
      loop: false,
    });
    this.$store.dispatch('initToken');
    this.$nextTick(() => {
      this.matchRightSwiper.controller.control = this.matchLeftSwiper;
      this.matchLeftSwiper.controller.control = this.matchRightSwiper;

      this.caseTopSwiper.controller.control = this.caseBottomSwiper;
      this.caseBottomSwiper.controller.control = this.caseTopSwiper;
    });
  },
  methods: {
    handleSearch() {
      this.$router.push({
        name: pageCode.DISCOVER,
        params: { searchText: this.searchText },
      });
    },
    handleSlick() {
      this.rightFirstSvgArrow.reset();
      this.rightFirstSvgArrow.play();
    },
  },
};
</script>

